import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture via cached loader
  const texture = ctx.textureLoader.load(config.assetUrls?.imageUrl);

  // Create plane geometry with 512:320 aspect ratio (1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1);

  // Create material with texture
  const material = new MeshBasicNodeMaterial({
    map: texture,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply scene position
  const pos = config.scenePosition || {};
  mesh.position.set(pos.x ?? 0, pos.y ?? 0, pos.z ?? 0);

  // Apply rotation if present
  if (pos.rotationXYZ) {
    mesh.rotation.order = 'XYZ';
    mesh.rotation.set(
      pos.rotationXYZ.x ?? 0,
      pos.rotationXYZ.y ?? 0,
      pos.rotationXYZ.z ?? 0
    );
  }

  // Apply scale if present
  if (pos.scaleXYZ) {
    mesh.scale.set(
      pos.scaleXYZ.x ?? 1,
      pos.scaleXYZ.y ?? 1,
      pos.scaleXYZ.z ?? 1
    );
  }

  // Initialize event handlers
  group.userData.handlers = {};

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return group;
}
